import { NextResponse } from "next/server";
import { checkRateLimit } from "@/lib/rate-limit";
import { trustedClientIp } from "@/app/api/_lib/client-ip";
import { currentUser } from "@/lib/auth";
import { insertDeployFunnelEvent } from "@/lib/deploy-funnel";

export const runtime = "nodejs";

/**
 * Deploy-funnel event sink. Called fire-and-forget by the customer deploy wizards
 * (components/customer/*DeployWizard.tsx) as a person moves through the steps, and
 * by the same wizards when a step throws / a provision call fails. Server-side
 * provisioning failures are recorded via `recordDeployFunnelError` (lib/deploy-funnel.ts)
 * rather than this HTTP path.
 *
 * Records one `DeployFunnelEvent`. Like /api/track it MUST NOT throw or block —
 * analytics is strictly best-effort. It attributes the signed-in account via
 * `currentUser()` (the auth cookie rides the POST) and the stable visitor cookie,
 * so an admin can later tie a stuck/errored session back to a real customer.
 */

const VID_COOKIE = "nx_vid";
const PRODUCTS = new Set(["vps", "game", "hosting", "email"]);
// "select" (2026-09-27): a real wizard SELECTION — which game/plan/term/region
// a customer picked — as opposed to "step" (reached) / "error" / "complete".
// See lib/deploy-funnel-client.ts's trackDeploySelect and
// lib/deploy-funnel.ts's deploySelections.
const TYPES = new Set(["step", "error", "complete", "select"]);
const MAX_DETAIL_LEN = 2000;

function readCookie(req: Request, name: string): string | null {
  const raw = req.headers.get("cookie");
  if (!raw) return null;
  for (const part of raw.split("; ")) {
    if (part.startsWith(`${name}=`)) return part.slice(name.length + 1);
  }
  return null;
}

function cleanId(v: unknown): string | null {
  if (typeof v !== "string") return null;
  const s = v.trim();
  if (!s || s.length > 64 || !/^[A-Za-z0-9._-]+$/.test(s)) return null;
  return s;
}

function cleanStr(v: unknown, max: number): string | null {
  if (typeof v !== "string") return null;
  const s = v.trim().slice(0, max);
  return s || null;
}

/** A "select" event's `detail` blob: must be a string, length-capped, and
 *  genuinely parseable JSON — never let a malformed payload reach the DB (or
 *  throw here; this route must never surface a capture failure). */
function cleanDetail(v: unknown): string | null {
  if (typeof v !== "string") return null;
  const s = v.slice(0, MAX_DETAIL_LEN);
  if (!s) return null;
  try {
    JSON.parse(s);
  } catch {
    return null;
  }
  return s;
}

export async function POST(req: Request) {
  try {
    const ip = trustedClientIp(req);
    const rl = checkRateLimit(`deploystep:${ip}`, { max: 120, windowMs: 60_000 });
    if (!rl.ok) return new NextResponse(null, { status: 204 });

    const body = (await req.json().catch(() => ({}))) as Record<string, unknown>;

    const product = typeof body.product === "string" ? body.product : "";
    if (!PRODUCTS.has(product)) return NextResponse.json({ ok: true });
    const step = cleanStr(body.step, 60);
